package com.rappistream.dashboardaggregator.infrastructure.history;  import jakarta.persistence.Column; import jakarta.persistence.Entity; import jakarta.persistence.GeneratedValue; import jakarta.persistence.GenerationType; import jakarta.persistence.Id; import jakarta.persistence.Table;  import java.time.Instant;  @Entity @Table(name = "order_history") public class OrderHistoryJpaEntity {      @Id     @GeneratedValue(strategy = GenerationType.IDENTITY)     private Long id;      @Column(name = "order_id", length = 64, nullable = false)     private String orderId;      @Column(name = "event_type", length = 32, nullable = false)     private String eventType;      @Column(name = "driver_id", length = 64)     private String driverId;      @Column(name = "occurred_at", nullable = false)     private Instant occurredAt;      public Long getId() { return id; }     public String getOrderId() { return orderId; }     public void setOrderId(String orderId) { this.orderId = orderId; }     public String getEventType() { return eventType; }     public void setEventType(String eventType) { this.eventType = eventType; }     public String getDriverId() { return driverId; }     public void setDriverId(String driverId) { this.driverId = driverId; }     public Instant getOccurredAt() { return occurredAt; }     public void setOccurredAt(Instant occurredAt) { this.occurredAt = occurredAt; } }
